<# .SYNOPSIS     Remediation script - removes selected Lenovo bloatware. Runs as SYSTEM via Intune. .DESCRIPTION     Removes:       - Lenovo Now                 (Inno Setup unins000.exe  -> /VERYSILENT)       - Lenovo Vantage Service     (Lenovo Uninstall.exe     -> /silent, verified)       - Lenovo Vantage frontend    (AppX E046963F.LenovoCompanion + provisioned)     KEEPS (never touched):       - Lenovo Smart Meeting Components (camera/AV effects)      Uninstall strings are read live from the registry (version-proof). Every     external uninstaller runs with a hard timeout so a stuck/interactive     uninstaller can never hang the device (lesson learned from McAfee). #>  $ErrorActionPreference = 'SilentlyContinue'  $workDir = Join-Path $env:ProgramData 'LenovoDebloat' New-Item -ItemType Directory -Path $workDir -Force | Out-Null Start-Transcript -Path (Join-Path $workDir 'debloat.log') -Append | Out-Null Write-Output "==== Lenovo debloat started $(Get-Date -Format s) as $env:USERNAME ===="  # --- helper: run an uninstaller with a hard timeout -------------------------- function Invoke-WithTimeout {     param([string]$FilePath, [string]$Arguments, [int]$TimeoutSec = 300)     try {         $p = Start-Process -FilePath $FilePath -ArgumentList $Arguments -PassThru -WindowStyle Hidden         if ($p.WaitForExit($TimeoutSec * 1000)) {             Write-Output "Exit $($p.ExitCode): $FilePath $Arguments"         } else {             Write-Output "TIMEOUT ${TimeoutSec}s -> killed: $FilePath $Arguments"             $p.Kill()         }     } catch { Write-Output "ERROR launching $FilePath : $($_.Exception.Message)" } }  # Exact DisplayNames to remove. Smart Meeting Components is intentionally absent. $targetNames = @('Lenovo Now', 'Lenovo Vantage Service')  $roots = @(     'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',     'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' )  # --- 1. Classic installs (Lenovo Now, Vantage Service) ----------------------- Get-ItemProperty $roots |     Where-Object { $targetNames -contains $_.DisplayName } |     ForEach-Object {         $name = $_.DisplayName         # Prefer a QuietUninstallString if Lenovo provided one         $u = $_.QuietUninstallString; if (-not $u) { $u = $_.UninstallString }         if (-not $u) { Write-Output "No uninstall string for $name"; return }          # Strip surrounding quotes to get the bare exe path         $exe = $u.Trim('"')         Write-Output "Uninstalling: $name  ($exe)"          if ($exe -match '(?i)msiexec') {             $guid = [regex]::Match($u, '\{[0-9A-Fa-f\-]{36}\}').Value             if ($guid) { Invoke-WithTimeout 'msiexec.exe' "/x $guid /qn /norestart" 300 }         }         elseif ($exe -match '(?i)unins\d+\.exe$') {             # Inno Setup uninstaller (Lenovo Now)             Invoke-WithTimeout $exe '/VERYSILENT /NORESTART /SUPPRESSMSGBOXES' 300         }         elseif ($exe -match '(?i)Uninstall\.exe$') {             # Lenovo Vantage Service custom uninstaller - /silent verified working             Invoke-WithTimeout $exe '/silent' 300         }         else {             Write-Output "Unknown uninstaller type for $name, trying -silent as best effort"             Invoke-WithTimeout $exe '-silent' 180         }     }  # --- 2. Vantage frontend AppX (installed + provisioned) ---------------------- Get-AppxPackage -AllUsers -Name 'E046963F.LenovoCompanion' | ForEach-Object {     try {         Remove-AppxPackage -AllUsers -Package $_.PackageFullName -ErrorAction Stop         Write-Output "Removed AppX: $($_.Name)"     } catch { Write-Output "AppX remove failed: $($_.Exception.Message)" } } Get-AppxProvisionedPackage -Online |     Where-Object { $_.DisplayName -like '*LenovoCompanion*' } |     ForEach-Object {         try {             Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName -ErrorAction Stop | Out-Null             Write-Output "Removed provisioned: $($_.PackageName)"         } catch { Write-Output "Provisioned remove failed: $($_.Exception.Message)" }     }  # --- 3. Log what Lenovo items remain (diagnostics) --------------------------- $remaining = (Get-ItemProperty $roots | Where-Object { $_.DisplayName -like '*Lenovo*' }).DisplayName Write-Output "Remaining Lenovo entries: $($remaining -join '; ')"  Write-Output "==== Lenovo debloat finished $(Get-Date -Format s) ====" Stop-Transcript | Out-Null exit 0